export function lastGamesFor(playerName: string, count = 5): SkaterGameLog[] {
  return skaterGameLogs
    .filter((g) => g.playerName === playerName)
    .sort((a, b) => b.date.localeCompare(a.date))
    .slice(0, count);
}
